import { getSettingsPageMetadata } from "@/modules/settings/lib/metadata";
import { TagsPage } from "@/modules/workspaces/settings/tags/page";

export const generateMetadata = () => getSettingsPageMetadata("common.tags");

export default TagsPage;

"use client";

import { useQuery } from "@tanstack/react-query";
import { getTags } from "../lib/api-client";
import { tagKeys } from "../lib/query";

/** A workspace's tags with their response counts — the table's only data source. */
export const useTags = (workspaceId: string) =>
  useQuery({
    queryKey: tagKeys.list(workspaceId),
    queryFn: ({ signal }) => getTags({ workspaceId, signal }),
  });

"use client";

import { useMutation, useQueryClient } from "@tanstack/react-query";
import { deleteTag } from "../lib/api-client";
import { tagKeys } from "../lib/query";

/** Delete a tag, then invalidate the list — replacing a `router.refresh()` full-page revalidation. */
export const useDeleteTag = (workspaceId: string) => {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: (variables: { tagId: string }) => deleteTag(variables),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: tagKeys.list(workspaceId) }),
  });
};

import type { TV3Tag } from "@/app/api/v3/tags/serializers";
import { parseV3ApiError } from "@/modules/api/lib/v3-client";

/**
 * Client fetchers for the tags v3 routes. Reads forward the TanStack `signal`; every call throws a parsed
 * `V3ApiError` on a non-2xx response, so the hooks can surface the server's own message.
 */

const BASE_PATH = "/api/v3/tags";

async function request<T>(url: string, init: RequestInit): Promise<T> {
  const response = await fetch(url, { cache: "no-store", ...init });
  if (!response.ok) {
    throw await parseV3ApiError(response);
  }
  return ((await response.json()) as { data: T }).data;
}

export async function getTags(params: { workspaceId: string; signal?: AbortSignal }): Promise<TV3Tag[]> {
  const query = new URLSearchParams({ workspaceId: params.workspaceId });
  return request<TV3Tag[]>(`${BASE_PATH}?${query.toString()}`, {
    method: "GET",
    signal: params.signal,
  });
}

export async function renameTag(params: { tagId: string; name: string }): Promise<TV3Tag> {
  return request<TV3Tag>(`${BASE_PATH}/${params.tagId}`, {
    method: "PATCH",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ name: params.name }),
  });
}

export async function deleteTag(params: { tagId: string }): Promise<{ id: string }> {
  return request<{ id: string }>(`${BASE_PATH}/${params.tagId}`, { method: "DELETE" });
}

export async function mergeTags(params: { tagId: string; newTagId: string }): Promise<{ id: string }> {
  return request<{ id: string }>(`${BASE_PATH}/${params.tagId}/merge`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ newTagId: params.newTagId }),
  });
}

/**
 * GET /api/v3/tags — list a workspace's tags with their response counts.
 *
 * Session-only, deliberately. These endpoints replace `authenticatedActionClient` server actions that
 * only ever ran for a signed-in user, so accepting `x-api-key` here would widen the surface rather than
 * migrate it.
 */
import { withV3ApiWrapper } from "@/app/api/v3/lib/api-wrapper";
import { listV3Tags } from "./lib/operations";
import { ZV3TagListQuery } from "./lib/schemas";

export const GET = withV3ApiWrapper({
  auth: "session",
  schemas: { query: ZV3TagListQuery },
  handler: async ({ authentication, parsedInput, requestId, instance }) =>
    listV3Tags({
      authentication,
      workspaceId: parsedInput.query.workspaceId,
      requestId,
      instance,
    }),
});

/**
 * PATCH  /api/v3/tags/{tagId} — rename a tag.
 * DELETE /api/v3/tags/{tagId} — delete a tag and its response links.
 *
 * The workspace is resolved from the tag, never from the request, so the caller cannot supply the scope
 * it is authorized against. Session-only, matching the actions these replace.
 */
import { withV3ApiWrapper } from "@/app/api/v3/lib/api-wrapper";
import { deleteV3Tag, renameV3Tag } from "../lib/operations";
import { ZV3RenameTagBody, ZV3TagIdParams } from "../lib/schemas";

export const PATCH = withV3ApiWrapper({
  auth: "session",
  action: "updated",
  targetType: "tag",
  schemas: { params: ZV3TagIdParams, body: ZV3RenameTagBody },
  handler: async ({ authentication, parsedInput, auditLog, requestId, instance }) =>
    renameV3Tag({
      authentication,
      tagId: parsedInput.params.tagId,
      name: parsedInput.body.name,
      auditLog,
      requestId,
      instance,
    }),
});

export const DELETE = withV3ApiWrapper({
  auth: "session",
  action: "deleted",
  targetType: "tag",
  schemas: { params: ZV3TagIdParams },
  handler: async ({ authentication, parsedInput, auditLog, requestId, instance }) =>
    deleteV3Tag({
      authentication,
      tagId: parsedInput.params.tagId,
      auditLog,
      requestId,
      instance,
    }),
});

import "server-only";
import { cache as reactCache } from "react";
import { prisma } from "@formbricks/database";
import { Prisma } from "@formbricks/database/prisma";
import { ZId } from "@formbricks/types/common";
import { DatabaseError } from "@formbricks/types/errors";
import { TTagsCount, TTagsOnResponses } from "@formbricks/types/tags";
import { andVisibleSurveys } from "@/lib/survey/visibility/predicate";
import { getUniqueConstraintFields, isUniqueConstraintError } from "../utils/prisma-constraint";
import { validateInputs } from "../utils/validate";

const selectTagsOnResponse = {
  tag: {
    select: {
      workspaceId: true,
    },
  },
};

export const addTagToRespone = async (responseId: string, tagId: string): Promise<TTagsOnResponses> => {
  try {
    await prisma.tagsOnResponses.create({
      data: {
        responseId,
        tagId,
      },
      select: selectTagsOnResponse,
    });

    return {
      responseId,
      tagId,
    };
  } catch (error) {
    if (isUniqueConstraintError(error)) {
      const fields = getUniqueConstraintFields(error);
      if (fields.includes("responseId") && fields.includes("tagId")) {
        // Idempotent: the tag is already on the response.
        return {
          responseId,
          tagId,
        };
      }
    }
    if (error instanceof Prisma.PrismaClientKnownRequestError) {
      throw new DatabaseError(error.message);
    }

    throw error;
  }
};

export const deleteTagOnResponse = async (responseId: string, tagId: string): Promise<TTagsOnResponses> => {
  try {
    await prisma.tagsOnResponses.delete({
      where: {
        responseId_tagId: {
          responseId,
          tagId,
        },
      },
      select: selectTagsOnResponse,
    });

    return {
      tagId,
      responseId,
    };
  } catch (error) {
    if (error instanceof Prisma.PrismaClientKnownRequestError) {
      throw new DatabaseError(error.message);
    }
    throw error;
  }
};

export const getTagsOnResponsesCount = reactCache(
  async (
    workspaceId: string,
    /** ENG-3282: the caller's survey-visibility clause, so a restricted survey's responses are not counted. */
    visibleSurveyWhere: Prisma.SurveyWhereInput
  ): Promise<TTagsCount> => {
    validateInputs([workspaceId, ZId]);

    try {
      const tagsCount = await prisma.tagsOnResponses.groupBy({
        by: ["tagId"],
        where: {
          response: {
            survey: {
              workspaceId,
              ...andVisibleSurveys(visibleSurveyWhere),
            },
          },
        },
        _count: {
          _all: true,
        },
      });

      return tagsCount.map((tagCount) => ({ tagId: tagCount.tagId, count: tagCount._count._all }));
    } catch (error) {
      if (error instanceof Prisma.PrismaClientKnownRequestError) {
        throw new DatabaseError(error.message);
      }
      throw error;
    }
  }
);

